<?php

namespace App\Support\DesignSystem;

use App\Http\Middleware\CollapseHtmlWhitespace;
use Illuminate\Support\Str;

/**
 * Builds the Storybook sources from the styleguide: each example rendered through Blade, the Design Tokens and
 * one story file per section. Storybook never re-implements a component, so it shows exactly what the site renders.
 */
final class StorybookExport
{
    public const GENERATED = 'storybook/generated';

    public const STORIES = 'storybook/stories';

    /**
     * Every generated file, keyed by its path from the repository root.
     *
     * @return array<string, string>
     */
    public static function files(): array
    {
        $leads = self::sectionLeads();
        $files = [
            self::GENERATED.'/examples.json' => self::json([
                'canvases' => ComponentCatalog::CANVASES,
                'examples' => self::examples(),
            ]),
            self::GENERATED.'/design.tokens.json' => rtrim(TokenDocument::current()->toJson())."\n",
        ];

        foreach (ComponentCatalog::sections() as $id => $section) {
            $files[self::STORIES.'/'.Str::lower($section['group']).'/'.$id.'.stories.js'] = self::storyFile($section, $leads[$id] ?? null);
        }

        return $files;
    }

    /**
     * @return array<string, array{section: string, title: string, description: string, canvas: string, html: string, source: string}>
     */
    private static function examples(): array
    {
        $previous = app()->getLocale();
        app()->setLocale(config('app.fallback_locale', 'en'));
        $origin = rtrim(url('/'), '/');

        try {
            return collect(ComponentCatalog::EXAMPLES)->map(function (array $example, string $name) use ($origin) {
                $html = CollapseHtmlWhitespace::collapse(view('styleguide.examples.'.$name)->render());
                $html = preg_replace('/<!--\[if (?:END)?BLOCK\]><!\[endif\]-->/', '', $html);

                return $example + [
                    'html' => trim(str_replace($origin.'/', '/', $html)),
                    'source' => trim(file_get_contents(resource_path('views/styleguide/examples/'.$name.'.blade.php'))),
                ];
            })->all();
        } finally {
            app()->setLocale($previous);
        }
    }

    /**
     * @param  array{group: string, title: string, examples: array<string, array{title: string}>}  $section
     */
    private static function storyFile(array $section, ?string $lead): string
    {
        $lines = [
            '// Generated by `php artisan design-system:storybook` from App\Support\DesignSystem\ComponentCatalog. Do not edit.',
            "import { exampleParameters, renderExample } from '../../render.js';",
            '',
            'export default {',
            '    title: '.self::js($section['group'].'/'.$section['title']).',',
            "    tags: ['autodocs'],",
        ];

        if ($lead) {
            $lines[] = '    parameters: { docs: { description: { component: '.self::js($lead).' } } },';
        }

        $lines[] = '};';

        foreach ($section['examples'] as $name => $example) {
            $lines[] = '';
            $lines[] = 'export const '.Str::studly($name).' = {';
            $lines[] = '    name: '.self::js($example['title']).',';
            $lines[] = '    render: () => renderExample('.self::js($name).'),';
            $lines[] = '    parameters: exampleParameters('.self::js($name).'),';
            $lines[] = '};';
        }

        return implode("\n", $lines)."\n";
    }

    /**
     * The lead paragraph of each styleguide section, so the Storybook docs open with the same guidance.
     *
     * @return array<string, string>
     */
    private static function sectionLeads(): array
    {
        preg_match_all('/<x-styleguide\.section id="([a-z-]+)" title="[^"]*" lead="([^"]*)"/', file_get_contents(resource_path('views/livewire/styleguide.blade.php')), $matches, PREG_SET_ORDER);

        return collect($matches)->mapWithKeys(fn (array $match) => [$match[1] => html_entity_decode($match[2], ENT_QUOTES)])->all();
    }

    private static function js(mixed $value): string
    {
        return json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    }

    private static function json(array $value): string
    {
        return json_encode($value, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR)."\n";
    }
}
